ALTER TABLE public.profiles ADD COLUMN access_type text NOT NULL DEFAULT 'interne';
CREATE OR REPLACE FUNCTION public.can_see_module(_uid uuid,_module_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role_slug(_uid,'super-admin') OR public.has_permission(_uid,'modules.configure') OR EXISTS(SELECT 1 FROM public.user_module_access WHERE user_id=_uid AND module_id=_module_id) OR EXISTS (SELECT 1 FROM public.modules c JOIN public.user_module_access a ON a.module_id=c.id WHERE c.parent_id=_module_id AND a.user_id=_uid) $$;
CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER roles_updated_at BEFORE UPDATE ON public.roles FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER modules_updated_at BEFORE UPDATE ON public.modules FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER connections_updated_at BEFORE UPDATE ON public.module_connections FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER settings_updated_at BEFORE UPDATE ON public.system_settings FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER company_updated_at BEFORE UPDATE ON public.company FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER subscriptions_updated_at BEFORE UPDATE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE FUNCTION public.attach_profile_company() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.company_id IS NULL THEN SELECT id INTO NEW.company_id FROM public.company LIMIT 1; END IF; RETURN NEW; END $$;
CREATE TRIGGER profiles_attach_company BEFORE INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.attach_profile_company();
CREATE OR REPLACE FUNCTION public.backfill_profiles_company() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.profiles SET company_id=NEW.id WHERE company_id IS NULL; RETURN NEW; END $$;
CREATE TRIGGER company_backfill_profiles AFTER INSERT ON public.company FOR EACH ROW EXECUTE FUNCTION public.backfill_profiles_company();
CREATE OR REPLACE FUNCTION public.subscription_set_end_date() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.end_date:=NEW.start_date + CASE NEW.plan WHEN 'MONTHLY' THEN interval '1 month' WHEN 'SEMI_ANNUAL' THEN interval '6 months' ELSE interval '12 months' END; RETURN NEW; END $$;
CREATE TRIGGER subscriptions_end_date BEFORE INSERT OR UPDATE OF plan,start_date ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.subscription_set_end_date();
CREATE OR REPLACE FUNCTION public.subscription_log_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.subscription_events(subscription_id,event,to_plan,to_status,actor_id) VALUES(NEW.id,'Subscription Created',NEW.plan,NEW.status,auth.uid()); RETURN NEW; END IF; IF NEW.plan IS DISTINCT FROM OLD.plan THEN INSERT INTO public.subscription_events(subscription_id,event,from_plan,to_plan,actor_id) VALUES(NEW.id,'Plan Changed',OLD.plan,NEW.plan,auth.uid()); END IF; IF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.subscription_events(subscription_id,event,from_status,to_status,actor_id) VALUES(NEW.id,CASE NEW.status WHEN 'SUSPENDED' THEN 'Subscription Suspended' WHEN 'CANCELLED' THEN 'Subscription Cancelled' WHEN 'EXPIRED' THEN 'Subscription Expired' WHEN 'ACTIVE' THEN 'Subscription Reactivated' ELSE 'Subscription Updated' END,OLD.status,NEW.status,auth.uid()); ELSIF NEW.start_date IS DISTINCT FROM OLD.start_date THEN INSERT INTO public.subscription_events(subscription_id,event,to_plan,to_status,actor_id) VALUES(NEW.id,'Subscription Renewed',NEW.plan,NEW.status,auth.uid()); END IF; RETURN NEW; END $$;
CREATE TRIGGER subscriptions_history AFTER INSERT OR UPDATE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.subscription_log_event();
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role_slug(_user_id,_role) $$;
REVOKE EXECUTE ON FUNCTION public.has_role(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,text) TO authenticated;